const stocks = $input.all().map(i => i.json);
const analyzed = stocks.filter(s => s.score !== null);

const counts = {
  total: stocks.length,
  analyzed: analyzed.length,
  STRONG_BUY: analyzed.filter(s => s.recommendation === 'STRONG_BUY').length,
  BUY: analyzed.filter(s => s.recommendation === 'BUY').length,
  HOLD: analyzed.filter(s => s.recommendation === 'HOLD').length,
  SELL: analyzed.filter(s => s.recommendation === 'SELL').length,
};

// 상위 5 매수 후보 (점수 높은 순)
const top5 = [...analyzed]
  .sort((a, b) => b.score - a.score)
  .slice(0, 5)
  .map(s => `  • *${s.name}* (${s.symbol}) — 점수 ${s.score}, ${(s.priceChangeRate*100).toFixed(1)}%`);

// 매도 주의 종목
const sell3 = analyzed
  .filter(s => s.recommendation === 'SELL')
  .sort((a, b) => a.score - b.score)
  .slice(0, 3)
  .map(s => `  • ${s.name} (${s.symbol}) — 점수 ${s.score}`);

const today = new Date().toLocaleDateString('ko-KR', { timeZone: 'Asia/Seoul', month: 'long', day: 'numeric', weekday: 'long' });

const message = [
  `📊 *StockGuide 오늘의 시장 요약*`,
  `_${today}_`,
  ``,
  `📈 추천 현황`,
  `  강한매수 ${counts.STRONG_BUY}개 | 매수 ${counts.BUY}개 | 관망 ${counts.HOLD}개 | 매도 ${counts.SELL}개`,
  ``,
  `🔥 오늘의 매수 후보 TOP 5`,
  ...top5,
  ``,
  ...(sell3.length > 0 ? [
    `⚠️ 매도 주의`,
    ...sell3,
    ``,
  ] : []),
  `_분석 기준 시각: ${new Date().toLocaleTimeString('ko-KR', { timeZone: 'Asia/Seoul' })}_`,
].join('\n');

return [{ json: { message } }];
